import re
from typing import List, Dict, Any

# Helpers assumed to be available in the environment
# node_by_title(doc, title), children(doc, node), scope_nodes(doc, scope)

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return a list of all distinct entities that appear in `scope`.

    Each entity is represented as ``{"id": "object_id", "description": "full description"}``.
    The id is the numeric object identifier used elsewhere in the document (e.g. "0", "1").
    """
    obj_node_title = f"{scope}: Objects"
    node = node_by_title(doc, obj_node_title)
    if not node or node.get("kind") != "list":
        return []

    out: List[Dict[str, str]] = []
    pattern = re.compile(r"Object\s+(\d+):\s*(.+)")
    for line in node.get("lines", []):
        m = pattern.match(line)
        if not m:
            continue
        obj_id, desc = m.group(1), m.group(2).strip()
        out.append({"id": obj_id, "description": desc})
    return out


def recorded_end(doc: Dict[str, Any], scope: str) -> float:
    """Return the last time point covered by the scope's records.

    The value is expressed as a float (frames are integers in the document).
    """
    max_frame = 0

    # 1. Motion log
    motion_node = node_by_title(doc, f"{scope}: Motion log")
    if motion_node and motion_node.get("kind") == "table":
        cols = motion_node["table"]["columns"]
        try:
            frame_col = cols.index("frame")
            for row in motion_node["table"]["rows"]:
                try:
                    f = int(row[frame_col])
                    if f > max_frame:
                        max_frame = f
                except (ValueError, IndexError):
                    continue
        except ValueError:
            pass

    # 2. Events list (may contain frames not present in motion log)
    events_node = node_by_title(doc, f"{scope}: Events")
    if events_node and events_node.get("kind") == "list":
        for line in events_node.get("lines", []):
            m = re.search(r"Frame\s+(\d+)", line)
            if m:
                try:
                    f = int(m.group(1))
                    if f > max_frame:
                        max_frame = f
                except ValueError:
                    continue

    return float(max_frame)


def observed_events(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all interaction events for `scope`.

    An interaction event is any line in the Events list that references
    two or more objects and contains a keyword indicating a collision
    (e.g. collide, hit, touch, meet, overlap, etc.).
    Each event dict has ``time``, ``kind``, and ``participants`` (sorted list of entity ids).
    """
    events: List[Dict[str, Any]] = []

    events_node = node_by_title(doc, f"{scope}: Events")
    if not events_node or events_node.get("kind") != "list":
        return events

    # Kinds of interaction words we look for in an event line
    interaction_keywords = r"\b(collide|collision|collided|touch|touches|meet|meeting|hit|hits|overlap|overlaps|overlapping)\b"

    # Regexes
    frame_pattern = re.compile(r"Frame\s+(\d+)")
    object_pattern = re.compile(r"Object\s+(\d+)")

    for line in events_node.get("lines", []):
        # Find all object ids in the line
        object_ids = object_pattern.findall(line)
        if len(object_ids) < 2:
            continue  # Need at least two objects to be an interaction

        # Check if any interaction keyword is present
        if not re.search(interaction_keywords, line, re.IGNORECASE):
            continue

        # Extract frame number
        m_frame = frame_pattern.search(line)
        if not m_frame:
            continue
        try:
            frame = float(m_frame.group(1))
        except ValueError:
            continue

        # Ensure participants are unique and sorted
        participants = sorted(set(object_ids))
        events.append(
            {
                "time": frame,
                "kind": "collide",
                "participants": participants,
            }
        )

    # Return events sorted by time
    events.sort(key=lambda e: e["time"])
    return events
